import React, { useState, useEffect } from "react";
import {
  Box,
  Tabs,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  TextField,
  Typography,
  Container,
  TablePagination,
  CircularProgress,
  IconButton,
  Link,
  InputAdornment,
  Grid,
} from "@mui/material";
import {
  Business as BusinessIcon,
  AddBusiness as AddBusinessIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search,
} from "@mui/icons-material";
import axios from "axios";
import Swal from "sweetalert2";

function TabPanel({ children, value, index, ...other }) {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`tabpanel-${index}`}
      aria-labelledby={`tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ p: 3 }}>{children}</Box>}
    </div>
  );
}

const Department = () => {
  const [tabValue, setTabValue] = useState(0);
  const [searchQuery, setSearchQuery] = useState("");
  const [departments, setDepartments] = useState([]);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalDepartments, setTotalDepartments] = useState(0);
  const [loading, setLoading] = useState(false);
  const [editMode, setEditMode] = useState(false);
  const [selectedDepartmentId, setSelectedDepartmentId] = useState(null);
  const [formData, setFormData] = useState({
    name: "",
    description: "",
  });
  const [errors, setErrors] = useState({});
  const [buttonLoading, setButtonLoading] = useState(false);
  const [expandedRows, setExpandedRows] = useState({}); // State to track expanded rows

  const token =
    typeof window !== "undefined" ? localStorage.getItem("token") : null;

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 1500,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
    customClass: {
      container: "swal-toast-container",
      popup: "swal-toast-popup",
    },
  });

  useEffect(() => {
    const styleSheet = document.createElement("style");
    styleSheet.textContent = `
      .swal-toast-container {
        z-index: 9999 !important;
      }
      .swal-toast-popup {
        font-family: 'Inter', sans-serif;
        font-size: 14px;
      }
    `;
    document.head.appendChild(styleSheet);
    return () => document.head.removeChild(styleSheet);
  }, []);

  const fetchDepartments = async () => {
    setLoading(true);
    try {
      const response = await axios.get("/department/list?paginate=true", {
        params: {
          page: page + 1,
          per_page: rowsPerPage,
          search: searchQuery,
        },
        headers: { Authorization: `Bearer ${token}` },
      });
      setDepartments(response.data.data.data);
      setTotalDepartments(response.data.data.total);
    } catch (error) {
      setDepartments([]);
      setTotalDepartments(0);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDepartments();
  }, [page, rowsPerPage, searchQuery]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);
    setEditMode(false);
    setFormData({ name: "", description: "" });
    setErrors({});
  };

  const handleInputChange = (event) => {
    const { name, value } = event.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
    setErrors((prev) => ({
      ...prev,
      [name]: "",
    }));
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.name.trim()) newErrors.name = "Name is required";
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSaveChanges = async () => {
    if (!validateForm()) return;
    setButtonLoading(true);
    const data = new FormData();
    data.append("name", formData.name);
    data.append("description", formData.description);

    try {
      const url = editMode
        ? `/department/edit/${selectedDepartmentId}`
        : "/department/add";
      const response = await axios.post(url, data, {
        headers: { Authorization: `Bearer ${token}` },
      });
      Toast.fire({
        icon: "success",
        title:
          response.data.message ||
          (editMode ? "Department updated" : "Department added"),
      });
      setTabValue(0);
      fetchDepartments();
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: error.response?.data?.message || "Failed to save department",
      });
    } finally {
      setButtonLoading(false);
    }
  };

  const handleCancel = () => {
    setEditMode(false);
    setFormData({ name: "", description: "" });
    setErrors({});
  };

  const handleEdit = async (id) => {
    try {
      const response = await axios.get(`/department/details/${id}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      const department = response.data.data;
      setFormData({
        name: department.name,
        description: department.description || "",
      });
      setSelectedDepartmentId(id);
      setEditMode(true);
      setTabValue(1);
    } catch (error) {
      Toast.fire({
        icon: "error",
        title: "Failed to fetch department details",
      });
    }
  };

  const handleDelete = (id) => {
    Swal.fire({
      title: "Are you sure?",
      text: "You won't be able to revert this!",
      icon: "warning",
      showCancelButton: true,
      confirmButtonColor: "#43B02A",
      cancelButtonColor: "#C92A20",
      confirmButtonText: "Yes, delete it!",
      cancelButtonText: "No, cancel",
      customClass: {
        container: "swal-toast-container",
        popup: "swal-toast-popup",
      },
    }).then((result) => {
      if (result.isConfirmed) {
        axios
          .get(`/department/delete/${id}`, {
            headers: { Authorization: `Bearer ${token}` },
          })
          .then((response) => {
            Toast.fire({
              icon: "success",
              title: response.data.message || "Department deleted successfully",
            });
            fetchDepartments();
          })
          .catch((error) => {
            Toast.fire({
              icon: "error",
              title:
                error.response?.data?.message || "Failed to delete department",
            });
          });
      }
    });
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const toggleExpand = (id) => {
    setExpandedRows((prev) => ({
      ...prev,
      [id]: !prev[id],
    }));
  };

  const MAX_LENGTH = 50; // Maximum characters to show before truncating

  return (
    <Grid container>
      <Box sx={{ mb: 2 }}>
        <TextField
          placeholder="Search departments..."
          value={searchQuery}
          onChange={(e) => {
            setSearchQuery(e.target.value);
            setPage(0);
          }}
          size="small"
          sx={{
            "& .MuiOutlinedInput-root": {
              borderRadius: 8,
              backgroundColor: "#fff",
              "& fieldset": { borderColor: "#e0e0e0" },
              "&:hover fieldset": { borderColor: "#bdbdbd" },
              "&.Mui-focused fieldset": { borderColor: "#4CAF50" },
              "& input": {
                padding: { xs: "6px 10px", sm: "8px 12px" },
                fontSize: { xs: "0.75rem", sm: "0.875rem" },
              },
            },
          }}
          InputProps={{
            startAdornment: (
              <InputAdornment position="start">
                <Search sx={{ color: "#666", fontSize: { xs: 18, sm: 20 } }} />
              </InputAdornment>
            ),
          }}
        />
      </Box>

      <Paper
        sx={{
          width: "100%",
          borderRadius: 2,
          boxShadow: 1,
          overflow: "hidden",
        }}
      >
        <Box sx={{ borderBottom: "1px solid #e0e0e0" }}>
          <Tabs
            value={tabValue}
            onChange={handleTabChange}
            sx={{
              "& .MuiTab-root": {
                textTransform: "none",
                fontWeight: 500,
                minHeight: 48,
                borderRadius: 1,
              },
              "& .Mui-selected": {
                backgroundColor: "#F97316 !important",
                color: "white !important",
              },
              "& .MuiTabs-indicator": { backgroundColor: "#fff", height: 2 },
            }}
          >
            <Tab
              icon={<BusinessIcon />}
              label="Department List"
              iconPosition="start"
              sx={{ gap: 1 }}
            />
            <Tab
              icon={editMode ? <EditIcon /> : <AddBusinessIcon />}
              label={editMode ? "Update Department" : "Add Department"}
              iconPosition="start"
              sx={{ gap: 1 }}
            />
          </Tabs>
        </Box>

        <TabPanel value={tabValue} index={0}>
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: "bold" }}>ID</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Name</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Description</TableCell>
                  <TableCell sx={{ fontWeight: "bold" }}>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {loading ? (
                  <TableRow>
                    <TableCell colSpan={4} align="center">
                      Loading...
                    </TableCell>
                  </TableRow>
                ) : Array.isArray(departments) && departments.length > 0 ? (
                  departments.map((department) => (
                    <TableRow
                      key={department.id}
                      sx={{ "&:hover": { backgroundColor: "#f9f9f9" } }}
                    >
                      <TableCell>{department.id}</TableCell>
                      <TableCell>{department.name}</TableCell>
                      <TableCell>
                        <Box sx={{ wordWrap: "break-word", maxWidth: "300px" }}>
                          {expandedRows[department.id]
                            ? department.description || "N/A"
                            : (department.description || "N/A").length >
                              MAX_LENGTH
                            ? `${(department.description || "N/A").slice(
                                0,
                                MAX_LENGTH
                              )}...`
                            : department.description || "N/A"}
                          {department.description &&
                            department.description.length > MAX_LENGTH && (
                              <Link
                                component="button"
                                onClick={() => toggleExpand(department.id)}
                                sx={{
                                  ml: 1,
                                  fontSize: "0.8rem",
                                  color: "#3B82F6",
                                }}
                              >
                                {expandedRows[department.id]
                                  ? "Show Less"
                                  : "Show More"}
                              </Link>
                            )}
                        </Box>
                      </TableCell>
                      <TableCell>
                        <Box sx={{ display: "flex", gap: 1 }}>
                          <Button
                            variant="contained"
                            size="small"
                            onClick={() => handleEdit(department.id)}
                            sx={{
                              backgroundColor: "#3B82F6",
                              "&:hover": { backgroundColor: "#3B82F6" },
                              textTransform: "none",
                              borderRadius: 3,
                              fontSize: "12px",
                              lineHeight: 1.5,
                            }}
                          >
                            Edit
                          </Button>
                          <IconButton
                            size="small"
                            onClick={() => handleDelete(department.id)}
                            sx={{
                              backgroundColor: "#C92A20",
                              "&:hover": { backgroundColor: "#b12419" },
                              color: "#fff",
                              width: "32px",
                              height: "32px",
                            }}
                          >
                            <DeleteIcon fontSize="small" />
                          </IconButton>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={4} align="center">
                      No data available
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
          <TablePagination
            rowsPerPageOptions={[5, 10, 25]}
            component="div"
            count={totalDepartments}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
          />
        </TabPanel>

        <TabPanel value={tabValue} index={1}>
          <Box sx={{ maxWidth: 600, mx: "auto" }}>
            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Name
            </Typography>
            <TextField
              fullWidth
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              error={!!errors.name}
              helperText={errors.name}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />
            <Typography
              variant="subtitle1"
              sx={{ mb: 1, fontWeight: "medium" }}
            >
              Description
            </Typography>
            <TextField
              fullWidth
              name="description"
              value={formData.description}
              onChange={handleInputChange}
              variant="outlined"
              size="small"
              multiline
              rows={4}
              sx={{
                "& .MuiOutlinedInput-root": { borderRadius: "4px" },
                mb: 2,
              }}
            />
            <Box sx={{ display: "flex", gap: 2, justifyContent: "flex-end" }}>
              <Button
                variant="contained"
                onClick={handleSaveChanges}
                disabled={buttonLoading}
                sx={{
                  backgroundColor: "#43B02A",
                  "&:hover": { backgroundColor: "#3a9624" },
                  textTransform: "none",
                  px: 3,
                  display: "flex",
                  alignItems: "center",
                  gap: 1,
                }}
              >
                {buttonLoading && (
                  <CircularProgress size={20} sx={{ color: "white" }} />
                )}
                {editMode ? "Update Department" : "Save Changes"}
              </Button>
              <Button
                variant="contained"
                onClick={handleCancel}
                sx={{
                  backgroundColor: "#C92A20",
                  "&:hover": { backgroundColor: "#b12419" },
                  textTransform: "none",
                  px: 3,
                }}
              >
                Cancel
              </Button>
            </Box>
          </Box>
        </TabPanel>
      </Paper>
    </Grid>
  );
};

export default Department;
